package com.nexusdrive.metadata.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="folders",uniqueConstraints=@UniqueConstraint(columnNames={"owner_id","parent_id","name"}))public class Folder{@Id private UUID id;@Column(name="owner_id",nullable=false)private UUID ownerId;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="parent_id")private Folder parent;@Column(nullable=false)private String name;@Column(name="full_path",nullable=false)private String fullPath;@Column(name="created_at",nullable=false)private Instant createdAt;@PrePersist void pre(){if(id==null)id=UUID.randomUUID();createdAt=Instant.now();}public UUID getId(){return id;}public UUID getOwnerId(){return ownerId;}public void setOwnerId(UUID v){ownerId=v;}public Folder getParent(){return parent;}public void setParent(Folder v){parent=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getFullPath(){return fullPath;}public void setFullPath(String v){fullPath=v;}public Instant getCreatedAt(){return createdAt;}}
